 const [compOffEntries,setCompOffEntries]=useState<CompOffEntry[]>([]);
 const [compOffHolidays,setCompOffHolidays]=useState<HolidayEntry[]>(()=>presetHolidays2026_2027());
 const [compOffDate,setCompOffDate]=useState(localDate());
 const [compOffFrom,setCompOffFrom]=useState(localDate().slice(0,7)+"-01");
 const [compOffTo,setCompOffTo]=useState(localDate());
 const [compOffNote,setCompOffNote]=useState("");
 const [holidayDate,setHolidayDate]=useState(localDate());
 const [holidayName,setHolidayName]=useState("");
 const compOffExpiry=compOffExpiryDate;
 const compOffEarnedEntries=()=>compOffEntries.filter(e=>e.type==="earned");
 const compOffUsedEntries=()=>compOffEntries.filter(e=>e.type==="used");
 const compOffAvailableEntries=(onDate=localDate())=>getCompOffAvailableEntries(compOffEntries,onDate);
 const compOffBalance=()=>compOffAvailableEntries(localDate()).length;
 const compOffExpiredCount=()=>compOffEarnedEntries().filter(e=>(e.expiresAt||compOffExpiry(e.date))<localDate()&&!compOffUsedEntries().some(u=>u.earnedEntryId===e.id)).length;
 const compOffDayType=(value:string)=>{if(!isValidISODate(value))return "";const d=new Date(value+"T12:00:00");const day=d.getDay();if(day===0)return "Sunday";if(day===6&&Math.ceil(d.getDate()/7)%2===0)return "2nd / 4th Saturday";if(compOffHolidays.some(h=>h.date===value))return "Public holiday";return "";};
 function addCompOffEarned(){const kind=compOffDayType(compOffDate);if(!kind){showToast("Selected date is not a configured non-working day");return}if(compOffEntries.some(e=>e.type==="earned"&&e.date===compOffDate)){showToast("Comp-off already recorded for this date");return}setCompOffEntries(old=>normalizeCompOffEntries([...old,{id:crypto.randomUUID(),type:"earned",date:compOffDate,expiresAt:compOffExpiry(compOffDate),notes:compOffNote.trim()||kind}]));setCompOffNote("");showToast("1 comp-off day earned · valid through "+compOffExpiry(compOffDate));}
 function addCompOffUsed(){const earned=compOffAvailableEntries(compOffDate)[0];if(!earned){showToast("No earned comp-off is available on the selected date");return}setCompOffEntries(old=>normalizeCompOffEntries([...old,{id:crypto.randomUUID(),type:"used",date:compOffDate,earnedEntryId:earned.id,notes:compOffNote.trim()||"Comp-off taken"}]));setCompOffNote("");showToast("Comp-off usage linked to earned date "+earned.date);}
 function editCompOffEntry(entry:CompOffEntry){const date=window.prompt("Entry date (YYYY-MM-DD)",entry.date);if(date===null)return;if(!isValidISODate(date)){showToast("Enter a valid date");return}const notes=window.prompt("Notes",entry.notes||"");if(notes===null)return;const normalized=normalizeCompOffEntries(compOffEntries);if(entry.type==="earned"&&hasLinkedCompOffUsage(normalized,entry.id)){showToast("This earned day has linked usage. Delete the usage first before changing its earning date.");return}if(entry.type==="used"&&!isValidCompOffUsageDate(normalized,entry.id,date)){showToast("Usage date must fall between the linked earned date and its three-month expiry.");return}if(entry.type==="earned"&&normalized.some(e=>e.id!==entry.id&&e.type==="earned"&&e.date===date)){showToast("An earned entry already exists for this date");return}setCompOffEntries(old=>normalizeCompOffEntries(old.map(e=>e.id===entry.id?{...e,date,notes,...(e.type==="earned"?{expiresAt:compOffExpiry(date)}:{})}:e)));}
 function deleteCompOffEntry(entry:CompOffEntry){const normalized=normalizeCompOffEntries(compOffEntries);if(entry.type==="earned"&&hasLinkedCompOffUsage(normalized,entry.id)){showToast("This earned day has already been used. Delete the linked usage entry first.");return}if(!window.confirm(entry.type==="used"?"Delete this comp-off usage? Its linked earned day will be available again only if it has not expired.":"Delete this earned comp-off entry?"))return;setCompOffEntries(old=>normalizeCompOffEntries(old.filter(e=>e.id!==entry.id)));showToast(entry.type==="used"?"Usage deleted; linked balance recalculated":"Earned comp-off entry deleted");}
 function exportCompOffExcel(){const rows=[["Type","Date","Notes"],...compOffEntries.filter(e=>e.date>=compOffFrom&&e.date<=compOffTo).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>[e.type==="earned"?"Earned":"Used",e.date,e.notes||""])];const csv="\uFEFF"+rows.map(row=>row.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\r\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="officeflow-comp-off-"+compOffFrom+"-to-"+compOffTo+".csv";a.click();URL.revokeObjectURL(url);}
 function saveMeeting(){const m=meetingDraft;if(!m.subject.trim()||!m.date||!m.start||!m.client.trim()){showToast("Complete the meeting details");return}const dates=meetingOccurrenceDates(m.date,m.recurrence as any,12);if(!dates.length){showToast("Enter a valid meeting date");return}if(hasMeetingConflict(meetings,m)){showToast("This meeting or one of its recurring dates overlaps an existing meeting. Choose another slot.");return}const seriesId=m.recurrence!=="None"?crypto.randomUUID():undefined;const occurrences=dates.map((date,index)=>({...m,id:crypto.randomUUID(),date,...(seriesId?{seriesId,occurrenceIndex:index+1}:{})}));setMeetings(old=>[...old,...occurrences]);setMeetingDraft(old=>({...old,client:"",contact:"",subject:"",notes:"",date:localDate(),start:"10:00"}));showToast(seriesId?occurrences.length+" recurring meetings scheduled":"Meeting scheduled");}
 function addCompOffHoliday(){if(!isValidISODate(holidayDate)||!holidayName.trim()){showToast("Enter a holiday name and date");return}setCompOffHolidays(old=>[...old.filter(h=>h.date!==holidayDate),{date:holidayDate,name:holidayName.trim()}].sort((a,b)=>a.date.localeCompare(b.date)));setHolidayName("");showToast("Holiday added");}
 const [diaryPeriod,setDiaryPeriod]=useState<"day"|"week"|"month">("day");
 const [diaryReportDate,setDiaryReportDate]=useState(localDate());
 const [diaryReportMember,setDiaryReportMember]=useState("All");
 const [meetings,setMeetings]=useState<{id:string;clientType:"existing"|"prospective";client:string;contact:string;subject:string;date:string;start:string;duration:number;mode:string;notes:string;recurrence:string;seriesId?:string;occurrenceIndex?:number}[]>([]);
 const [meetingDraft,setMeetingDraft]=useState({clientType:"existing" as "existing"|"prospective",client:"",contact:"",subject:"",date:localDate(),start:"10:00",duration:60,mode:"Office",notes:"",recurrence:"None"});
 function diaryRange(){const d=new Date(diaryReportDate+"T12:00:00");if(diaryPeriod==="month")return [new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10),new Date(d.getFullYear(),d.getMonth()+1,0).toISOString().slice(0,10)] as const;if(diaryPeriod==="week"){const start=new Date(d);start.setDate(d.getDate()-d.getDay());const end=new Date(start);end.setDate(start.getDate()+6);return [start.toISOString().slice(0,10),end.toISOString().slice(0,10)] as const;}return [diaryReportDate,diaryReportDate] as const;}
 function exportDiaryReport(){const [from,to]=diaryRange();const rows=[["Date","Client","Task / matter","Entry","Person"],...tasks.flatMap(t=>(t.activity||[]).filter(e=>e.at.slice(0,10)>=from&&e.at.slice(0,10)<=to&&(e.message.startsWith("Work performed")||e.message.startsWith("Checklist completed:"))&&(diaryReportMember==="All"||e.actor===diaryReportMember)).map(e=>[e.at.slice(0,10),t.client,t.title,e.message,e.actor||""]))];const csv="\\uFEFF"+rows.map(row=>row.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\\r\\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="officeflow-diary-"+diaryPeriod+"-"+from+"-to-"+to+".csv";a.click();URL.revokeObjectURL(url);}
 function addDiaryEntry(){const task=tasks.find(t=>t.id===diaryTaskId);if(!task){showToast("Select an existing task");return}if(!diaryText.trim()){showToast("Describe the work completed");return}const now=new Date();const clock=now.toTimeString().slice(0,8);const at=new Date(diaryDate+"T"+clock).toISOString();const duration=diaryDuration.trim();const entry={at,actor:profileDisplayName||workspaceDisplayName||"Charan Reddy",message:"Work performed"+(duration?" · "+duration:"")+" — "+diaryText.trim()};setTasks(old=>old.map(t=>t.id===task.id?{...t,activity:[...(t.activity||[]),entry]}:t));setDiaryText("");setDiaryDuration("");showToast("Work recorded against "+task.client)}
 function exportMyWorkPNG(){const canvas=document.createElement("canvas");const ctx=canvas.getContext("2d");if(!ctx)return;const entries=tasks.flatMap(t=>(t.activity||[]).filter(e=>e.at.slice(0,10)===diaryDate&&(e.message.startsWith("Work performed")||e.message.startsWith("Checklist completed:"))).map(e=>t.client+" | "+t.title+" | "+e.message));const lines=["MY WORK REPORT - "+diaryDate,"",...entries];ctx.font="22px Arial";const wrapped:string[]=[];for(const line of lines){if(!line){wrapped.push("");continue}let cur="";for(const word of line.split(" ")){const test=cur?cur+" "+word:word;if(ctx.measureText(test).width>940&&cur){wrapped.push(cur);cur=word}else cur=test}wrapped.push(cur)}canvas.width=1020;canvas.height=Math.max(360,140+wrapped.length*36);ctx.fillStyle="#eaf7f1";ctx.fillRect(0,0,1020,canvas.height);ctx.fillStyle="#063a34";ctx.fillRect(0,0,1020,85);ctx.fillStyle="#fff";ctx.font="bold 30px Arial";ctx.fillText("OFFICEFLOW / MY WORK",40,55);wrapped.forEach((v,i)=>{ctx.fillStyle=i===0?"#087c67":"#173e35";ctx.font=i===0?"bold 24px Arial":"22px Arial";ctx.fillText(v,40,135+i*36)});const a=document.createElement("a");a.download="officeflow-work-"+diaryDate+".png";a.href=canvas.toDataURL("image/png");a.click();showToast("PNG exported")}
