 useEffect(()=>{if(!remindersEnabled||typeof Notification==="undefined"||Notification.permission!=="granted")return;const check=()=>{const day=localDate();if(localStorage.getItem("officeflow-reminder-date")===day)return;const due=tasks.filter(t=>!["Filed / completed","Done"].includes(t.status)&&Boolean(t.internalDue||t.due||t.statutoryDue||t.nextClientFollowUp)&&(((t.internalDue||t.due)&&((t.internalDue||t.due)<=day))||(t.statutoryDue&&t.statutoryDue>=day&&t.statutoryDue<=indiaDateOffset(7))||(t.nextClientFollowUp&&t.nextClientFollowUp<=day)));if(due.length)new Notification("OfficeFlow: action needed",{body:due.length+" task(s) need attention for deadlines or client follow-ups."});safeStorageSet("officeflow-reminder-date",day)};check();const timer=window.setInterval(check,60*60*1000);return()=>window.clearInterval(timer)},[session?.user?.id,remindersEnabled,tasks]);
