 function updateStatus(id:string,status:Status){const existing=tasks.find(t=>t.id===id);let pendingNote="";let nextFollowUp="";if(status==="Partially replied"){const note=window.prompt("What is still pending?");if(note===null)return;pendingNote=note;nextFollowUp=window.prompt("Optional follow-up date (YYYY-MM-DD)","")||"";}if(workspaceRole==="junior"&&existing?.approvalStatus&&existing.approvalStatus!=="approved"){showToast("This draft must be approved by a manager before work can begin");return;}if(["Filed / completed","Done","Closed"].includes(status)&&!existing?.filingAckDocument){setToast("Upload the filing acknowledgement before closing this task");setTimeout(()=>setToast(""),3000);return;}const at=new Date().toISOString();if(existing?.roundId){const reply=roundStatusFromTaskStatus(status);if(reply)setMatterRounds(old=>old.map(r=>r.id===existing.roundId?{...r,replyStatus:reply,notes:status==="Partially replied"?pendingNote||r.notes:r.notes}:r));}setTasks(old=>old.map(t=>t.id===id?{...t,status,lastProgressUpdate:at,completedAt:["Filed / completed","Done","Closed"].includes(status)?at:status==="Approved"?t.completedAt:undefined,reworkCount:status==="Rework required"?(t.reworkCount||0)+1:t.reworkCount,nextClientFollowUp:nextFollowUp||t.nextClientFollowUp,activity:[...(t.activity||[]),{at,actor:"Charan Reddy",message:"Status changed to "+status+(pendingNote?" · Pending: "+pendingNote:"")+(nextFollowUp?" · Follow-up: "+nextFollowUp:"")}]}:t));recordAudit("Status changed",tasks.find(t=>t.id===id)?.title,status);setToast("Task updated");setTimeout(()=>setToast(""),2200)}
