 ctx.fillStyle="#f6f7fb";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#282447";ctx.font="bold 28px Arial";ctx.fillText("OFFICEFLOW · "+(mode==="junior"?"MY WORK REPORT":"JUNIOR WORK REPORT"),pad,43);ctx.fillStyle="#6f7186";ctx.font="14px Arial";ctx.fillText("Generated "+new Date().toLocaleDateString("en-IN")+" · "+rows.length+" task(s)",pad,70);
 const tableY=96;let x=pad;ctx.fillStyle="#7266e8";ctx.fillRect(pad,tableY,widths.reduce((a,b)=>a+b,0),42);ctx.font="bold 13px Arial";ctx.fillStyle="#ffffff";headers.forEach((h,i)=>{ctx.fillText(h,x+10,tableY+25);x+=widths[i]});
 let y=tableY+42;prepared.forEach((row,ri)=>{const h=rowHeights[ri];ctx.fillStyle=ri%2===0?"#ffffff":"#f0f1f8";ctx.fillRect(pad,y,widths.reduce((a,b)=>a+b,0),h);ctx.strokeStyle="#e3e5ee";ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,y+h);ctx.lineTo(canvas.width-pad,y+h);ctx.stroke();let cx=pad;row.forEach((lines,ci)=>{ctx.save();ctx.beginPath();ctx.rect(cx+6,y+3,widths[ci]-12,h-6);ctx.clip();ctx.fillStyle="#292b3d";ctx.font=ci===0?"bold 12px Arial":"12px Arial";lines.forEach((line,li)=>ctx.fillText(line,cx+10,y+21+li*lineH));ctx.restore();cx+=widths[ci]});y+=h});
 ctx.fillStyle="#77798b";ctx.font="11px Arial";ctx.fillText("OfficeFlow · Internal work allocation",pad,canvas.height-18);
 canvas.toBlob(blob=>{if(!blob){showToast("Could not create report image");return}const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="officeflow-"+mode+"-work-"+localDate()+".png";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);showToast("PNG report exported") },"image/png");
