async function registerWorkspaceMember(e:React.FormEvent){
 e.preventDefault();
 if(!supabase||!session?.user||workspaceRole!=="manager"){setMemberMessage("Only a signed-in manager can add workspace members.");return}
 setMemberBusy(true);setMemberMessage("");
 try{
  const {error}=await supabase.rpc("officeflow_register_member",{p_email:newMember.email.trim(),p_role:newMember.role,p_display_name:newMember.display_name.trim(),p_phone_number:newMember.phone_number.trim()});
  if(error)throw error;
  const {data:workspaceData,error:workspaceError}=await supabase.rpc("officeflow_get_workspace");
  if(workspaceError)throw workspaceError;
  setWorkspaceMembers(Array.isArray((workspaceData as any)?.members)?(workspaceData as any).members:[]);
  setMemberMessage("Workspace access granted. The user should sign in again to load their role.");
  setNewMember({email:"",display_name:"",phone_number:"",role:"junior"});
 }catch(err){setMemberMessage(err instanceof Error?err.message:"Could not add workspace member.");}
 finally{setMemberBusy(false)}
}
async function changeAccountEmail(e:React.FormEvent){e.preventDefault();if(!supabase||!session?.user){setAccountMessage("Sign in with your Supabase account to change your email.");return}const nextEmail=newAccountEmail.trim().toLowerCase();if(!nextEmail||nextEmail===session.user.email?.toLowerCase()){setAccountMessage("Enter a different valid email address.");return}setAccountBusy(true);setAccountMessage("");try{const {error}=await supabase.auth.updateUser({email:nextEmail});if(error)throw error;setAccountMessage("Email change requested. Check the new email address (and your current address if prompted) to confirm the change.");setNewAccountEmail("");}catch(err){setAccountMessage(err instanceof Error?err.message:"Could not request email change.");}finally{setAccountBusy(false)}}
async function changeAccountPassword(e:React.FormEvent){e.preventDefault();if(!supabase||!session?.user?.email){setAccountMessage("Sign in with your Supabase account to change your password.");return}if(newAccountPassword.length<8){setAccountMessage("Use at least 8 characters for the new password.");return}if(newAccountPassword!==confirmAccountPassword){setAccountMessage("The new password and confirmation do not match.");return}setAccountBusy(true);setAccountMessage("");try{const {error:reauthError}=await supabase.auth.signInWithPassword({email:session.user.email,password:currentAccountPassword});if(reauthError)throw new Error("Current password could not be verified. Check it and try again.");const {error}=await supabase.auth.updateUser({password:newAccountPassword});if(error)throw error;setCurrentAccountPassword("");setNewAccountPassword("");setConfirmAccountPassword("");setAccountMessage("Password updated successfully.");}catch(err){setAccountMessage(err instanceof Error?err.message:"Could not update password.");}finally{setAccountBusy(false)}}
async function handleAuth(e:React.FormEvent){e.preventDefault();if(!supabase){setAuthMessage("Cloud configuration is missing. Please contact the workspace administrator.");return}setAuthBusy(true);setAuthMessage("");try{localStorage.removeItem("officeflow-local-mode");setLocalMode(false);if(authMode==="signup"){const {data,error}=await supabase.auth.signUp({email:authEmail.trim(),password:authPassword});if(error)throw error;if(!data.session)setAuthMessage("Account created. Check your email to confirm the account, then sign in.");else setAuthMessage("Account created. Loading your workspace…");}else{const {error}=await supabase.auth.signInWithPassword({email:authEmail.trim(),password:authPassword});if(error)throw error;setAuthMessage("Signed in. Loading workspace…");}}catch(e){setAuthMessage(e instanceof Error?e.message:"Authentication failed. Please try again.");}finally{setAuthBusy(false)}}
 async function resetPassword(){if(!supabase||!authEmail.trim()){setAuthMessage("Enter your email address first.");return}const {error}=await supabase.auth.resetPasswordForEmail(authEmail.trim(),{redirectTo:window.location.origin});setAuthMessage(error?error.message:"If an account exists for this email, a password reset link has been sent.");}
 function clientWhatsApp(t:Task){const message=encodeURIComponent("Dear "+(t.client||"Client")+",\nThis is a follow-up regarding "+t.title+".\nFinancial year / assessment year: "+(t.financialYear||"-")+" / "+(t.assessmentYear||"-")+".\nPlease share the pending information/documents or update us on the status. Thank you.");window.open("https://wa.me/?text="+message,"_blank","noopener,noreferrer")}
 function markFollowUp(t:Task){const at=localDate();recordAudit("Client contacted",t.title,"Follow-up recorded on "+at);setTasks(old=>old.map(x=>x.id===t.id?{...x,lastClientFollowUp:at,activity:[...(x.activity||[]),{at:new Date().toISOString(),actor:"Charan Reddy",message:"Client follow-up recorded"}]}:x));setToast("Follow-up recorded");setTimeout(()=>setToast(""),2200)}
 function rescheduleFollowUp(t:Task){const date=window.prompt("Next follow-up date (YYYY-MM-DD)",t.nextClientFollowUp||localDate());if(!date)return;if(!isValidISODate(date)){window.alert("Enter a real date in YYYY-MM-DD format (for example, 2026-11-05).");return}recordAudit("Follow-up rescheduled",t.title,"Next follow-up: "+date);setTasks(old=>old.map(x=>x.id===t.id?{...x,nextClientFollowUp:date,activity:[...(x.activity||[]),{at:new Date().toISOString(),actor:"Charan Reddy",message:"Next client follow-up rescheduled to "+date}]}:x));setToast("Follow-up rescheduled");setTimeout(()=>setToast(""),2200)}
 function whatsapp(t:Task){const name=t.juniors[0];let phone=(name&&juniorDirectory[name]||"").replace(/\D/g,"");if(!phone){const entered=window.prompt("Enter WhatsApp number for "+(name||"assigned junior")+" with country code:");if(!entered)return;phone=entered.replace(/\D/g,"");if(phone.length<10){window.alert("Enter a valid phone number including country code.");return}if(name)setJuniorDirectory(old=>({...old,[name]:phone}))}const title=t.title||t.matterName||"Tax notice";const issue=title.replace(/\s+/g," ").trim();const details=(t.description||"")+" "+(t.notes||"");const provision=details.match(/(?:Detected provision|provision)\s*:\s*([^\n.]+)/i);const issueText=provision?issue+" ("+provision[1].trim()+")":issue;const type=(t.taskType+" "+t.category+" "+t.matterType+" "+title).toLowerCase();let action="Review the notice and related records, identify the issue, gather supporting evidence, and prepare an issue-specific draft reply with annexures for review.";if(/itat|tribunal/.test(type))action="Review the appeal grounds and hearing directions, verify the paper book and evidence, and prepare issue-wise written submissions for review.";else if(/appeal|cit\(a\)|nfac/.test(type))action="Check the order and grounds of appeal, compile supporting evidence, and prepare the issue-wise submissions and annexures for review.";else if(/tds|tcs|traces/.test(type))action="Reconcile the notice with TDS/TCS returns, challans and ledgers; identify the default and prepare the correction/reply with evidence.";else if(/penalty/.test(type))action="Verify the penalty charge and underlying assessment, collect supporting evidence, and prepare a point-wise reply to the proposed penalty.";else if(/reassessment|148a|148/.test(type))action="Review the reassessment reasons and requested information, verify return/transaction records, and prepare an issue-wise response with evidence.";else if(/scrutiny|143/.test(type))action="Answer each scrutiny query against the return, books and reconciliations; prepare supporting workings and an evidence-backed response.";else if(/142|information request/.test(type))action="Prepare a point-by-point response to each information request and attach the relevant reconciliations and supporting records.";const message=encodeURIComponent("Client: "+(t.client||"Not specified")+"\nAY: "+(t.assessmentYear||"Not specified")+"\nIssue: "+issueText+"\nArticle action: "+action);window.open("https://wa.me/"+phone+"?text="+message,"_blank","noopener,noreferrer")}


 if(!ready||!authReady||(supabase&&session&&!cloudHydrated&&cloudStatus!=="Cloud sync failed — local copy retained"&&cloudStatus!=="Secure workspace unavailable"))return <main className="app"><div className="auth-shell"><div className="auth-card"><div className="brand"><div className="brand-mark">o</div><span>office<span className="brand-light">flow</span></span></div><p>Loading your workspace…</p></div></div></main>;
